import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.BuUvxvtQ.js";const m=JSON.parse('{"title":"How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/how-it-works.md","filePath":"web-app/how-it-works.md"}'),s={name:"web-app/how-it-works.md"};function d(i,e,n,l,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h1><p>Understanding what happens behind a single recommendation helps you get more out of Sky Style. This page explains the end-to-end flow, the weather sources, and the AI models.</p><h2 id="the-end-to-end-flow" tabindex="-1">The end-to-end flow <a class="header-anchor" href="#the-end-to-end-flow" aria-label="Permalink to &quot;The end-to-end flow&quot;">​</a></h2><p>When you generate a recommendation, Sky Style runs this sequence:</p><ol><li><strong>Resolve your location</strong> — from GPS (if you&#39;ve consented) or a manual city/coordinate search. City searches are geocoded via OpenStreetMap&#39;s Nominatim service (up to 5 matches, cached for 1 hour).</li><li><strong>Fetch weather data</strong> — from one or more sources (see below). Results are cached to avoid redundant calls.</li><li><strong>Aggregate sources</strong> — when multiple sources return data, Sky Style averages the numeric fields and keeps each source&#39;s reading to pass to the AI for richer context.</li><li><strong>Build the AI prompt</strong> — combining the weather snapshot, your <a href="./dashboard.html#closet">closet</a> items, your <a href="./settings.html#profile">gender context</a>, your unit preference, and (optionally) your location if you&#39;ve consented to share it.</li><li><strong>Call the AI</strong> — using the selected model (see <a href="#ai-models">AI models</a>).</li><li><strong>Return the recommendation</strong> — outfit text, reasoning, the weather used, and the model that generated it.</li><li><strong>Track usage</strong> — your daily <a href="#usage-limits">usage counters</a> increment.</li></ol><h2 id="weather-sources" tabindex="-1">Weather sources <a class="header-anchor" href="#weather-sources" aria-label="Permalink to &quot;Weather sources&quot;">​</a></h2><p>Sky Style uses several weather data sources. Which ones are used depends on your location and which API keys the deployment has configured.</p><h3 id="built-in-sources" tabindex="-1">Built-in sources <a class="header-anchor" href="#built-in-sources" aria-label="Permalink to &quot;Built-in sources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>When it&#39;s used</th><th>Key required?</th></tr></thead><tbody><tr><td><strong>Bureau of Meteorology (BOM)</strong></td><td>Australia only — when your coordinates fall inside Australia&#39;s bounding box.</td><td>No (free)</td></tr><tr><td><strong>OpenWeatherMap</strong></td><td>Primary source outside Australia (and supplementary inside Australia).</td><td>Yes (<code>OPENWEATHER_API_KEY</code>)</td></tr><tr><td><strong>Open-Meteo</strong></td><td>Always attempted (free, no key).</td><td>No</td></tr><tr><td><strong>WeatherAPI.com</strong></td><td>Optional supplementary source.</td><td>Yes (<code>WEATHERAPI_KEY</code>)</td></tr><tr><td><strong>Visual Crossing</strong></td><td>Optional supplementary source.</td><td>Yes (<code>VISUALCROSSING_API_KEY</code>)</td></tr><tr><td><strong>Pirate Weather</strong></td><td>Optional supplementary source.</td><td>Yes (<code>PIRATEWEATHER_API_KEY</code>)</td></tr></tbody></table><h3 id="multi-source-aggregation" tabindex="-1">Multi-source aggregation <a class="header-anchor" href="#multi-source-aggregation" aria-label="Permalink to &quot;Multi-source aggregation&quot;">​</a></h3><p>When more than one source returns data, Sky Style:</p><ul><li><strong>Averages</strong> the numeric fields (temperature, humidity, wind speed, etc.) for the displayed weather.</li><li><strong>Keeps</strong> each individual source&#39;s reading and passes all of them to the AI as context, so the recommendation accounts for agreement and disagreement between sources.</li><li>Marks the source as <code>Multi</code> when multiple sources contributed.</li></ul><p>A source that fails to return data is silently dropped — the recommendation still works as long as at least one source succeeds.</p><h3 id="accuracy-score" tabindex="-1">Accuracy score <a class="header-anchor" href="#accuracy-score" aria-label="Permalink to &quot;Accuracy score&quot;">​</a></h3><p>For BOM data, Sky Style computes the distance to the nearest reporting weather station and assigns an accuracy score:</p><table tabindex="0"><thead><tr><th>Distance to nearest station</th><th>Accuracy</th></tr></thead><tbody><tr><td>Less than 10 km</td><td>High</td></tr><tr><td>10–50 km</td><td>Medium</td></tr><tr><td>More than 50 km</td><td>Low</td></tr></tbody></table><p>This helps you judge how local the reading is.</p><h3 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h3><p>Weather data is cached in-memory to avoid redundant API calls. Each source has its own cache duration:</p><table tabindex="0"><thead><tr><th>Source</th><th>Cache TTL</th></tr></thead><tbody><tr><td>OpenWeatherMap</td><td>15 minutes</td></tr><tr><td>BOM</td><td>30 minutes</td></tr><tr><td>Open-Meteo</td><td>30 minutes</td></tr><tr><td>Custom (Pro)</td><td>10 minutes</td></tr><tr><td>Multi (aggregated)</td><td>15 minutes</td></tr></tbody></table><h3 id="hourly-forecast" tabindex="-1">Hourly forecast <a class="header-anchor" href="#hourly-forecast" aria-label="Permalink to &quot;Hourly forecast&quot;">​</a></h3><p>Some sources (Open-Meteo, WeatherAPI.com, Visual Crossing, Pirate Weather) also return an <strong>hourly forecast</strong> — a sequence of upcoming hours with time, temperature, description, rain chance, and wind speed. This powers the Weather Planning panel on the dashboard.</p><div class="tip custom-block"><p class="custom-block-title">Source picker</p><p>Pro users can choose which source to use for a given recommendation via the <strong>source picker</strong> (4/day on Free, unlimited on Pro). This is separate from custom sources — see <a href="./custom-weather-sources.html">Custom weather sources</a>.</p></div><h2 id="ai-models" tabindex="-1">AI models <a class="header-anchor" href="#ai-models" aria-label="Permalink to &quot;AI models&quot;">​</a></h2><p>Sky Style supports three AI providers, with model priority depending on your plan.</p><h3 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provider</th><th>Models</th></tr></thead><tbody><tr><td>OpenAI</td><td>GPT-4o, GPT-4o Mini</td></tr><tr><td>Google Gemini</td><td>Gemini 2.5 Flash, Gemini 2.5 Flash Lite, Gemma 4 31B, Gemma 4 26B</td></tr><tr><td>Mistral AI</td><td>Mistral Large, Mistral Small, Ministral 8B</td></tr></tbody></table><p>Gemma models are served through the Gemini provider — no separate key is required for them.</p><h3 id="model-priority" tabindex="-1">Model priority <a class="header-anchor" href="#model-priority" aria-label="Permalink to &quot;Model priority&quot;">​</a></h3><p>When multiple server-side keys are configured, Sky Style tries models in this order:</p><ul><li><strong>Pro users</strong>: OpenAI → Gemini → Gemma → Mistral Large → Mistral Small → Ministral</li><li><strong>Free users</strong>: Gemini → Mistral Small → Gemma → Ministral</li></ul><p>Free users do not get OpenAI models (to control cost). The first available model in your tier&#39;s priority list is used. If a provider&#39;s key isn&#39;t configured server-side, its models are skipped.</p><h3 id="bring-your-own-key-byok" tabindex="-1">Bring Your Own Key (BYOK) <a class="header-anchor" href="#bring-your-own-key-byok" aria-label="Permalink to &quot;Bring Your Own Key (BYOK)&quot;">​</a></h3><p>Pro and Dev users can override the server-side provider by entering their own key for OpenAI, Gemini, or Mistral in the dashboard&#39;s BYOK panel:</p><ul><li>When a BYOK key is set, requests for that provider use your key instead of Sky Style&#39;s.</li><li>BYOK keys are stored <strong>only in your browser</strong> and are sent solely for the AI request.</li><li>A custom prompt can replace the default Sky Style prompt (must include JSON output instructions).</li></ul><p>See <a href="./dashboard.html#bring-your-own-key-pro-dev">Dashboard → BYOK</a>.</p><h2 id="usage-limits" tabindex="-1">Usage limits <a class="header-anchor" href="#usage-limits" aria-label="Permalink to &quot;Usage limits {#usage-limits}&quot;">​</a></h2><p>Each plan has daily counters that reset at midnight UTC:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Free</th><th>Demo</th><th>Pro</th><th>Dev</th></tr></thead><tbody><tr><td>AI uses</td><td>20/day</td><td>200/day</td><td>Unlimited</td><td>Unlimited</td></tr><tr><td>Follow-ups</td><td>40/day</td><td>400/day</td><td>400/day</td><td>Unlimited</td></tr><tr><td>Closet uses</td><td>4/day</td><td>40/day</td><td>Unlimited</td><td>Unlimited</td></tr><tr><td>Source picks</td><td>4/day</td><td>40/day</td><td>Unlimited</td><td>Unlimited</td></tr><tr><td>Model switches</td><td>2/day</td><td>20/day</td><td>Unlimited</td><td>Unlimited</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Model switches are separate</p><p><strong>Model switches</strong> (changing which AI model is used) are a separate daily counter from <strong>AI uses</strong>. On the Free plan you can switch models 2 times per day, independent of your 20 AI uses. Pro and Dev have unlimited switches.</p></div><p>The <strong>Demo</strong> tier is only created automatically when the deployment is a preview/development environment; it multiplies the free limits by 10 for testing.</p>',41)])])}const p=t(s,[["render",d]]);export{m as __pageData,p as default};
